      announceCopy(msgEl, regionEl);
    }).catch(() => {
      // API exists but permission denied or other failure — fall back.
      try {
        regionEl.select();
        document.execCommand('copy');
        announceCopy(msgEl, regionEl);
      } catch (e) {
        msgEl.textContent = 'Copy failed';
      }
    });
  } else {
